Here is the commit message:
erofs: fix the out-of-bounds nameoff handling for trailing
 dirents

Currently we already have boundary-checks for nameoffs, but the trailing
dirents are special since the namelens are calculated with strnlen()
with unchecked nameoffs.

If a crafted EROFS has a trailing dirent with nameoff >= maxsize,
maxsize - nameoff can underflow, causing strnlen() to read past the
directory block.

nameoff0 should also be verified to be a multiple of
`sizeof(struct erofs_dirent)` as well [1].

[1] https://sashiko.dev/#/patchset/20260416063511.3173774-1-hsiangkao%40linux.alibaba.com

Fixes: 3aa8ec716e52 ("staging: erofs: add directory operations")
Fixes: 33bac912840f ("staging: erofs: keep corrupted fs from crashing kernel in erofs_readdir()")
Reported-by: Yuhao Jiang <danisjiang@gmail.com>
Reported-by: Junrui Luo <moonafterrain@outlook.com>
Closes: https://lore.kernel.org/r/A0FD7E0F-7558-49B0-8BC8-EB1ECDB2479A@outlook.com
Cc: stable@vger.kernel.org
Signed-off-by: Gao Xiang <hsiangkao@linux.alibaba.com>
Reviewed-by: Chao Yu <chao@kernel.org>

Here is the root cause:
The bug occurred in the trailing dirent handling within `erofs_fill_dentries`. For the last dirent in a directory block, the code computed `de_namelen` using `strnlen(de_name, maxsize - nameoff)` without first verifying that `nameoff` is less than `maxsize`. If a crafted EROFS image has a trailing dirent with `nameoff >= maxsize`, the subtraction `maxsize - nameoff` underflows (producing a very large unsigned value), causing `strnlen` to read out-of-bounds memory past the directory block. Additionally, the initial `nameoff0` check in `erofs_readdir` did not enforce alignment to `sizeof(struct erofs_dirent)`, allowing further structural inconsistencies.

Here is the patch:

 static int erofs_fill_dentries(struct inode *dir, struct dir_context *ctx,
 			       void *dentry_blk, struct erofs_dirent *de,
 			       unsigned int nameoff0, unsigned int maxsize)
 {
 	const struct erofs_dirent *end = dentry_blk + nameoff0;

 	while (de < end) {
 		unsigned char d_type = fs_ftype_to_dtype(de->file_type);
 		unsigned int nameoff = le16_to_cpu(de->nameoff);
 		const char *de_name = (char *)dentry_blk + nameoff;
 		unsigned int de_namelen;

-		/* the last dirent in the block? */
-		if (de + 1 >= end)
-			de_namelen = strnlen(de_name, maxsize - nameoff);
-		else
+		/* non-trailing dirent in the directory block? */
+		if (de + 1 < end)
 			de_namelen = le16_to_cpu(de[1].nameoff) - nameoff;
+		else if (maxsize <= nameoff)
+			goto err_bogus;
+		else
+			de_namelen = strnlen(de_name, maxsize - nameoff);

-		/* a corrupted entry is found */
-		if (nameoff + de_namelen > maxsize ||
-		    de_namelen > EROFS_NAME_LEN) {
-			erofs_err(dir->i_sb, "bogus dirent @ nid %llu",
-				  EROFS_I(dir)->nid);
-			DBG_BUGON(1);
-			return -EFSCORRUPTED;
-		}
+		/* a corrupted entry is found (including negative namelen) */
+		if (!in_range32(de_namelen, 1, EROFS_NAME_LEN) ||
+		    nameoff + de_namelen > maxsize)
+			goto err_bogus;

 		if (!dir_emit(ctx, de_name, de_namelen,
 			      erofs_nid_to_ino64(EROFS_SB(dir->i_sb),
 						 le64_to_cpu(de->nid)), d_type))
 			return 1;
 		++de;
 		ctx->pos += sizeof(struct erofs_dirent);
 	}
 	return 0;
+err_bogus:
+	erofs_err(dir->i_sb, "bogus dirent @ nid %llu", EROFS_I(dir)->nid);
+	DBG_BUGON(1);
+	return -EFSCORRUPTED;
 }

 static int erofs_readdir(struct file *f, struct dir_context *ctx)
 {
 	struct inode *dir = file_inode(f);
 	struct erofs_buf buf = __EROFS_BUF_INITIALIZER;
 	struct super_block *sb = dir->i_sb;
 	struct file_ra_state *ra = &f->f_ra;
 	unsigned long bsz = sb->s_blocksize;
 	unsigned int ofs = erofs_blkoff(sb, ctx->pos);
 	pgoff_t ra_pages = DIV_ROUND_UP_POW2(
 			EROFS_I_SB(dir)->dir_ra_bytes, PAGE_SIZE);
 	pgoff_t nr_pages = DIV_ROUND_UP_POW2(dir->i_size, PAGE_SIZE);
 	int err = 0;
 	bool initial = true;

 	buf.mapping = dir->i_mapping;
 	while (ctx->pos < dir->i_size) {
 		erofs_off_t dbstart = ctx->pos - ofs;
 		struct erofs_dirent *de;
 		unsigned int nameoff, maxsize;

 		if (fatal_signal_pending(current)) {
 			err = -ERESTARTSYS;
 			break;
 		}

 		/* readahead blocks to enhance performance for large directories */
 		if (ra_pages) {
 			pgoff_t idx = DIV_ROUND_UP_POW2(ctx->pos, PAGE_SIZE);
 			pgoff_t pages = min(nr_pages - idx, ra_pages);

 			if (pages > 1 && !ra_has_index(ra, idx))
 				page_cache_sync_readahead(dir->i_mapping, ra,
 							  f, idx, pages);
 		}

 		de = erofs_bread(&buf, dbstart, true);
 		if (IS_ERR(de)) {
 			erofs_err(sb, "failed to readdir of logical block %llu of nid %llu",
 				  erofs_blknr(sb, dbstart), EROFS_I(dir)->nid);
 			err = PTR_ERR(de);
 			break;
 		}

 		nameoff = le16_to_cpu(de->nameoff);
-		if (nameoff < sizeof(struct erofs_dirent) || nameoff >= bsz) {
+		if (!nameoff || nameoff >= bsz || (nameoff % sizeof(*de))) {
 			erofs_err(sb, "invalid de[0].nameoff %u @ nid %llu",
 				  nameoff, EROFS_I(dir)->nid);
 			err = -EFSCORRUPTED;
 			break;
 		}

 		maxsize = min_t(unsigned int, dir->i_size - dbstart, bsz);
 		/* search dirents at the arbitrary position */
 		if (initial) {
 			initial = false;
 			ofs = roundup(ofs, sizeof(struct erofs_dirent));
 			ctx->pos = dbstart + ofs;
 		}

 		err = erofs_fill_dentries(dir, ctx, de, (void *)de + ofs,
 					  nameoff, maxsize);
 		if (err)
 			break;
 		ctx->pos = dbstart + maxsize;
 		ofs = 0;
 		cond_resched();
 	}
 	erofs_put_metabuf(&buf);
 	if (EROFS_I(dir)->dot_omitted && ctx->pos == dir->i_size) {
 		if (!dir_emit_dot(f, ctx))
 			return 0;
 		++ctx->pos;
 	}
 	return err < 0 ? err : 0;
 }



